package kr.blackwiki.smp;
import org.bukkit.*;
import org.bukkit.block.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.block.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.*;
import org.bukkit.event.world.ChunkLoadEvent;
import org.bukkit.inventory.*;
import org.bukkit.persistence.PersistentDataType;
import java.util.*;
import java.util.logging.Level;
/** Native player receipts and a durable item escrow keep GUI withdrawal replay-safe. */
final class GraveService implements Listener {
    private final BlackWikiSMP p;final GraveLedger ledger;private final NamespacedKey marker,receiptKey,backupKey;private boolean fault;
    private record Site(UUID world,int x,int y,int z){}
    private long indexed=-1;private final Map<Site,UUID> sites=new HashMap<>();
    GraveService(BlackWikiSMP p)throws Exception{this.p=p;marker=new NamespacedKey(p,"grave-id");receiptKey=new NamespacedKey(p,"grave-receipts");backupKey=new NamespacedKey(p,"grave-backup-payload");ledger=new GraveLedger(p.getDataFolder().toPath().resolve("graves.yml"));for(var g:ledger.all())for(String item:g.items())if(!item.isEmpty())Objects.requireNonNull(VaultService.decode(item));}
    private boolean due(GraveLedger.Grave g,long now){return GraveRules.expired(g.created(),p.upgrades.graveExpiryEpoch,now);}
    private boolean closed(GraveLedger.Grave g){return g.state()==GraveLedger.State.EMPTY||g.state()==GraveLedger.State.CANCELLED||g.state()==GraveLedger.State.EXPIRED;}
    private String remaining(GraveLedger.Grave g){return "소멸까지 "+Rules.duration(GraveRules.remainingSeconds(g.created(),p.upgrades.graveExpiryEpoch,System.currentTimeMillis()))+" · 남은 아이템도 삭제";}
    void tick(){expireAt(System.currentTimeMillis());}
    void expireAt(long now){if(fault)return;try{List<GraveLedger.Grave> expired=ledger.all().stream().filter(g->!closed(g)&&due(g,now)).map(GraveLedger.Grave::expire).toList();if(!expired.isEmpty()){ledger.putAll(expired);for(var g:expired)removeMarker(g);ledger.compact();}}catch(Exception ex){fail(null,ex);}}
    private Set<String> receipts(Player a){String value=a.getPersistentDataContainer().getOrDefault(receiptKey,PersistentDataType.STRING,"");return new LinkedHashSet<>(value.isEmpty()?List.of():Arrays.asList(value.split("\n")));}
    private boolean has(Player a,String value){return receipts(a).contains(value);}
    private void receipt(Player a,String value){Set<String> all=receipts(a);all.add(value);if(all.size()>1000)throw new IllegalStateException("Too many unresolved grave receipts");a.getPersistentDataContainer().set(receiptKey,PersistentDataType.STRING,String.join("\n",all));}
    private void clean(Player a){if(p.backups.running())return;boolean changed=a.getPersistentDataContainer().has(backupKey);a.getPersistentDataContainer().remove(backupKey);Set<String> all=receipts(a);changed|=all.removeIf(value->{try{String[] s=value.split(":",2);UUID id=UUID.fromString(s[1]);if(s[0].equals("death")){var g=ledger.get(id);return g!=null&&g.state()!=GraveLedger.State.PREPARED;}if(s[0].equals("loot"))return ledger.all().stream().noneMatch(g->id.equals(g.token()));return false;}catch(Exception ex){return false;}});if(changed){a.getPersistentDataContainer().set(receiptKey,PersistentDataType.STRING,String.join("\n",all));a.saveData();}}
    private World world(GraveLedger.Grave g){return Bukkit.getWorld(g.worldId());}
    private Location at(GraveLedger.Grave g){World w=world(g);return w==null?null:new Location(w,g.x(),g.y(),g.z());}
    private UUID id(Block block){if(!(block.getState() instanceof TileState tile))return null;String value=tile.getPersistentDataContainer().get(marker,PersistentDataType.STRING);try{return value==null?null:UUID.fromString(value);}catch(IllegalArgumentException ex){return null;}}
    private boolean grave(Block block){return id(block)!=null;}
    private boolean adjacentChest(Block block){for(BlockFace face:List.of(BlockFace.NORTH,BlockFace.SOUTH,BlockFace.EAST,BlockFace.WEST))if(block.getRelative(face).getType()==Material.CHEST)return true;return false;}
    private boolean graveInventory(InventoryHolder holder){if(holder instanceof Chest chest)return grave(chest.getBlock());if(holder instanceof DoubleChest chest)return graveInventory(chest.getLeftSide())||graveInventory(chest.getRightSide());return false;}
    private Location spot(Location death){World w=death.getWorld();if(w==p.queue.world||p.safe(death))return null;int x=death.getBlockX(),z=death.getBlockZ();if(p.boundaryWorld(w)){int cx=(int)p.cfg().getDouble("border.center-x"),cz=(int)p.cfg().getDouble("border.center-z");x=Math.clamp(x,cx-19999,cx+19999);z=Math.clamp(z,cz-19999,cz+19999);}int y=Math.clamp(death.getBlockY(),w.getMinHeight()+1,w.getMaxHeight()-2);if(death.getY()<w.getMinHeight()+1)y=Math.clamp(w.getHighestBlockYAt(x,z)+1,w.getMinHeight()+1,w.getMaxHeight()-2);for(int r=0;r<=4;r++)for(int dy=0;dy<=5;dy++)for(int dx=-r;dx<=r;dx++)for(int dz=-r;dz<=r;dz++){if(Math.max(Math.abs(dx),Math.abs(dz))!=r||y+dy>=w.getMaxHeight()-1)continue;Location loc=new Location(w,x+dx,y+dy,z+dz);if(!p.safe(loc)&&!p.outside(loc)&&loc.getBlock().getType().isAir()&&!adjacentChest(loc.getBlock()))return loc;}return null;}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void death(PlayerDeathEvent e){if(!p.cfg().getBoolean("graves.enabled",true)||e.getKeepInventory()||e.getDrops().isEmpty())return;Player a=e.getEntity();boolean prepared=false;if(fault){e.getDrops().clear();e.setKeepInventory(true);a.saveData();return;}try{
        List<String> items=e.getDrops().stream().filter(it->it!=null&&!it.getType().isAir()).map(VaultService::encode).toList();if(items.isEmpty())return;ItemStack[] kept=InventoryPlan.add(new ItemStack[36],e.getItemsToKeep().stream().map(ItemStack::clone).toList());if(kept==null)throw new IllegalStateException("Kept death items exceed storage");Location chosen=spot(a.getLocation()),loc=chosen==null?a.getLocation():chosen;var g=new GraveLedger.Grave(UUID.randomUUID(),a.getUniqueId(),System.currentTimeMillis(),loc.getWorld().getName(),loc.getWorld().getUID(),loc.getBlockX(),loc.getBlockY(),loc.getBlockZ(),true,GraveLedger.State.PREPARED,items,null,null,-1);ledger.put(g);prepared=true;
        e.getDrops().clear();e.setKeepInventory(true);e.getItemsToKeep().clear();a.getInventory().clear();a.getInventory().setStorageContents(kept);receipt(a,"death:"+g.id());if(p.backups.running())backupPayload(a,g);a.saveData();g=g.state(GraveLedger.State.OPEN);ledger.put(g);if(chosen!=null)g=place(g);clean(a);p.tell(a,(g.virtual()?"스폰에서 /무덤 으로 복구":"사망 무덤: "+g.world()+" "+g.x()+", "+g.y()+", "+g.z())+" · 아이템 "+items.size()+"묶음 · 10분 후 소멸");
    }catch(Exception ex){e.getDrops().clear();e.setKeepInventory(true);if(!prepared)a.saveData();fail(a,ex);}}
    private GraveLedger.Grave place(GraveLedger.Grave g)throws Exception{if(closed(g))return g;Location loc=at(g);if(loc==null)return g;Block block=loc.getBlock();UUID existing=id(block);if(!block.getType().isAir()&&!g.id().equals(existing)&&!(existing==null&&block.getState() instanceof Chest old&&old.getBlockInventory().isEmpty()&&old.getBlockData() instanceof org.bukkit.block.data.type.Chest data&&data.getType()==org.bukkit.block.data.type.Chest.Type.SINGLE))return g;if(block.getType().isAir()){if(adjacentChest(block))return g;block.setType(Material.CHEST,false);}if(!(block.getState() instanceof Chest chest))return g;chest.getPersistentDataContainer().set(marker,PersistentDataType.STRING,g.id().toString());chest.customName(BlackWikiSMP.text(p.data.name(g.owner())+"의 무덤"));if(!chest.update(true,false))throw new java.io.IOException("Could not save grave marker");if(!g.virtual())return g;var next=g.physical(false);ledger.put(next);return next;}
    /** Repair legacy marker loss without overwriting a player's non-empty or unrelated chest. */
    private GraveLedger.Grave reachable(GraveLedger.Grave g)throws Exception{
        if(g.virtual()||g.state()!=GraveLedger.State.OPEN)return g;Location loc=at(g);if(loc==null)return g;Block b=loc.getBlock();UUID mark=id(b);
        if(g.id().equals(mark))return g;
        if(b.getType().isAir())return place(g);
        if(b.getState() instanceof Chest chest&&mark==null&&chest.getBlockData() instanceof org.bukkit.block.data.type.Chest data&&data.getType()==org.bukkit.block.data.type.Chest.Type.SINGLE&&chest.getBlockInventory().isEmpty())return place(g);
        // The coordinate now belongs to something else. Escrow stays intact and owner can recover at spawn.
        var next=g.physical(true);ledger.put(next);return next;
    }
    private UUID resolve(Block block)throws Exception{
        UUID markerId=id(block);if(markerId!=null)return markerId;if(block.getType()!=Material.CHEST)return null;
        if(indexed!=ledger.revision()){sites.clear();for(var g:ledger.all())if(!g.virtual()&&g.state()==GraveLedger.State.OPEN)sites.put(new Site(g.worldId(),g.x(),g.y(),g.z()),g.id());indexed=ledger.revision();}
        UUID key=sites.get(new Site(block.getWorld().getUID(),block.getX(),block.getY(),block.getZ()));if(key==null)return null;var g=reachable(ledger.get(key));return g.virtual()?null:g.id();
    }
    private void removeMarker(GraveLedger.Grave g){Location loc=at(g);if(loc!=null&&loc.getWorld().isChunkLoaded(g.x()>>4,g.z()>>4)&&g.id().equals(id(loc.getBlock())))loc.getBlock().setType(Material.AIR,false);}
    void reconcile(Player a){if(fault||p.backups.running())return;expireAt(System.currentTimeMillis());if(fault)return;try{for(var recovery:backupPayload(a))if(ledger.get(recovery.id())==null&&has(a,"death:"+recovery.id()))ledger.put(due(recovery,System.currentTimeMillis())?recovery.expire():recovery.state(GraveLedger.State.OPEN).physical(true));for(var original:ledger.all()){var g=original;if(g.state()==GraveLedger.State.PREPARED&&g.owner().equals(a.getUniqueId())){g=g.state(has(a,"death:"+g.id())?GraveLedger.State.OPEN:GraveLedger.State.CANCELLED);ledger.put(g);}if(g.token()!=null&&g.recipient().equals(a.getUniqueId())){g=g.settle(has(a,"loot:"+g.token()));ledger.put(g);}if(closed(g))removeMarker(g);}clean(a);ledger.compact();}catch(Exception ex){fail(a,ex);}}
    private List<GraveLedger.Grave> backupPayload(Player a)throws Exception{byte[] bytes=a.getPersistentDataContainer().get(backupKey,PersistentDataType.BYTE_ARRAY);if(bytes==null)return new ArrayList<>();try(var in=new java.util.zip.GZIPInputStream(new java.io.ByteArrayInputStream(bytes))){byte[] raw=in.readNBytes(16777217);if(raw.length>16777216)throw new IllegalStateException("Oversized grave recovery payload");return new ArrayList<>(Arrays.asList(new com.google.gson.Gson().fromJson(new String(raw,java.nio.charset.StandardCharsets.UTF_8),GraveLedger.Grave[].class)));}}
    private void backupPayload(Player a,GraveLedger.Grave grave)throws Exception{var all=backupPayload(a);all.add(grave);var out=new java.io.ByteArrayOutputStream();try(var zip=new java.util.zip.GZIPOutputStream(out)){zip.write(new com.google.gson.Gson().toJson(all).getBytes(java.nio.charset.StandardCharsets.UTF_8));}a.getPersistentDataContainer().set(backupKey,PersistentDataType.BYTE_ARRAY,out.toByteArray());}
    void afterBackup(){for(Player a:Bukkit.getOnlinePlayers())reconcile(a);}
    @EventHandler(priority=EventPriority.LOW) public void join(PlayerJoinEvent e){reconcile(e.getPlayer());}
    @EventHandler(priority=EventPriority.MONITOR) public void chunk(ChunkLoadEvent e){if(fault)return;expireAt(System.currentTimeMillis());if(fault)return;
        // Scan markers too: compacted expired records must not leave orphan chests.
        for(BlockState tile:e.getChunk().getTileEntities())if(tile instanceof Chest){UUID key=id(tile.getBlock());if(key!=null){var g=ledger.get(key);if(g==null||closed(g))tile.getBlock().setType(Material.AIR,false);}}
        for(var g:ledger.all())if(g.worldId().equals(e.getWorld().getUID())&&(g.x()>>4)==e.getChunk().getX()&&(g.z()>>4)==e.getChunk().getZ()){if(closed(g))removeMarker(g);else if(g.state()==GraveLedger.State.OPEN&&!g.virtual())try{reachable(g);}catch(Exception ex){p.getLogger().log(Level.WARNING,"Could not restore grave "+g.id(),ex);}}
    }
    private boolean access(Player a,GraveLedger.Grave g){if(due(g,System.currentTimeMillis())){expireAt(System.currentTimeMillis());a.closeInventory();p.tell(a,"10분이 지나 무덤과 남은 아이템이 소멸했습니다.");return false;}if(fault){p.tell(a,"무덤 저장 오류입니다. 관리자 확인 후 재시작하세요.");return false;}if(a.isDead()||p.queue.waiting(a))return false;if(g.virtual()||world(g)==null){if(!a.getUniqueId().equals(g.owner())||!p.safe(a.getLocation())){p.tell(a,"복구 무덤은 소유자가 스폰에서 열 수 있습니다.");return false;}}else{Location loc=at(g);if(a.getWorld()!=loc.getWorld()||a.getLocation().distanceSquared(loc.clone().add(.5,.5,.5))>36){p.tell(a,"무덤 좌표로 이동하세요: "+g.world()+" "+g.x()+", "+g.y()+", "+g.z());return false;}long lock=p.cfg().getLong("graves.owner-lock-seconds",0)*1000;if(!a.getUniqueId().equals(g.owner())&&System.currentTimeMillis()<g.created()+lock){p.tell(a,"소유자 보호 시간이 남았습니다.");return false;}}return true;}
    void open(Player a,UUID id,int page){var g=ledger.get(id);if(g==null||g.state()!=GraveLedger.State.OPEN)return;try{g=reachable(g);}catch(Exception ex){fail(a,ex);return;}if(!access(a,g))return;if(g.token()!=null){Player recipient=Bukkit.getPlayer(g.recipient());if(recipient!=null){reconcile(recipient);g=ledger.get(id);}if(g==null||g.state()!=GraveLedger.State.OPEN)return;if(g.token()!=null){p.tell(a,"이전 회수의 저장 확인을 기다리고 있습니다. 수령자가 접속하면 자동 확인합니다.");return;}}List<Integer> indices=new ArrayList<>();for(int i=0;i<g.items().size();i++)if(!g.items().get(i).isEmpty())indices.add(i);page=Math.clamp(page,0,Math.max(0,(indices.size()-1)/36));int current=page;Gui.Menu m=p.gui.make(a,p.data.name(g.owner())+"의 무덤 · "+(page+1));for(int i=page*36;i<Math.min(page*36+36,indices.size());i++){int index=indices.get(i),slot=9+i-page*36;String expected=g.items().get(index);m.inventory.setItem(slot,VaultService.decode(expected));m.actions.put(slot,b->{take(b,id,index,expected);open(b,id,current);});}p.gui.pages(m,page,indices.size(),b->open(b,id,current-1),b->open(b,id,current+1));m.inventory.setItem(48,Gui.item(Material.PAPER,"클릭: 한 묶음 전체 회수","가방 공간 부족 시 보관 유지","기본값: 다른 플레이어도 현장 약탈 가능",remaining(g)));p.gui.show(a,m);}
    boolean take(Player a,UUID id,int slot,String expected){var g=ledger.get(id);if(g==null||g.state()!=GraveLedger.State.OPEN||g.token()!=null||slot<0||slot>=g.items().size()||!g.items().get(slot).equals(expected)||expected.isEmpty()||!access(a,g))return false;if(p.backups.running()){p.tell(a,"백업 완료 후 이용하세요.");return false;}ItemStack[] next=InventoryPlan.add(a.getInventory().getStorageContents(),List.of(VaultService.decode(expected)));if(next==null){p.tell(a,"가방에 받을 공간이 없습니다.");return false;}try{UUID token=UUID.randomUUID();g=g.reserve(a.getUniqueId(),token,slot);ledger.put(g);receipt(a,"loot:"+token);a.getInventory().setStorageContents(next);a.saveData();g=g.settle(true);ledger.put(g);clean(a);if(g.state()==GraveLedger.State.EMPTY){removeMarker(g);a.closeInventory();p.tell(a,"무덤을 모두 회수했습니다.");}return true;}catch(Exception ex){fail(a,ex);return false;}}
    void list(Player a,int page){if(p.queue.waiting(a))return;expireAt(System.currentTimeMillis());List<GraveLedger.Grave> all=ledger.all().stream().filter(g->g.owner().equals(a.getUniqueId())&&(g.state()==GraveLedger.State.OPEN||g.state()==GraveLedger.State.PREPARED)).sorted(java.util.Comparator.comparingLong(GraveLedger.Grave::created).reversed()).toList();page=Math.clamp(page,0,Math.max(0,(all.size()-1)/36));int current=page;Gui.Menu m=p.gui.make(a,"내 사망 무덤 · "+(page+1));for(int i=page*36;i<Math.min(page*36+36,all.size());i++){var g=all.get(i);p.gui.button(m,9+i-page*36,Material.CHEST,"무덤 "+g.id().toString().substring(0,8),b->open(b,g.id(),0),g.world()+" "+g.x()+", "+g.y()+", "+g.z(),g.virtual()||world(g)==null?"스폰에서 복구 가능":"좌표로 이동 후 클릭","남은 묶음: "+g.items().stream().filter(s->!s.isEmpty()).count(),remaining(g));}p.gui.pages(m,page,all.size(),b->list(b,current-1),b->list(b,current+1));p.gui.show(a,m);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false) public void interact(PlayerInteractEvent e){if(e.getAction()!=Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null)return;try{UUID id=resolve(e.getClickedBlock());if(id==null)return;e.setCancelled(true);if(e.getHand()==EquipmentSlot.HAND)open(e.getPlayer(),id,0);}catch(Exception ex){e.setCancelled(true);fail(e.getPlayer(),ex);}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void breakBlock(BlockBreakEvent e){if(grave(e.getBlock())){e.setCancelled(true);p.tell(e.getPlayer(),"무덤을 열어 회수하세요. 10분 후 남은 아이템과 함께 소멸합니다.");}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void placeChest(BlockPlaceEvent e){if(e.getBlockPlaced().getType()!=Material.CHEST)return;for(BlockFace face:List.of(BlockFace.NORTH,BlockFace.SOUTH,BlockFace.EAST,BlockFace.WEST))if(grave(e.getBlockPlaced().getRelative(face))){e.setCancelled(true);p.tell(e.getPlayer(),"무덤 옆에는 연결 상자를 놓을 수 없습니다.");return;}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void explode(EntityExplodeEvent e){e.blockList().removeIf(this::grave);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void explode(BlockExplodeEvent e){e.blockList().removeIf(this::grave);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void burn(BlockBurnEvent e){if(grave(e.getBlock()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void hopper(InventoryMoveItemEvent e){if(graveInventory(e.getSource().getHolder())||graveInventory(e.getDestination().getHolder()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void inventory(InventoryOpenEvent e){if(graveInventory(e.getInventory().getHolder()))e.setCancelled(true);}
    int count(){expireAt(System.currentTimeMillis());return (int)ledger.all().stream().filter(g->g.state()==GraveLedger.State.OPEN).count();}
    private void fail(Player a,Exception ex){fault=true;if(a!=null)p.tell(a,"무덤 저장 오류로 작업을 잠갔습니다. 기록을 보존하고 관리자 확인 후 재시작하세요.");p.getLogger().log(Level.SEVERE,"Grave transaction locked; retain graves.yml and native player data together",ex);}
}
